const input = $json.body ?? $json;

const name = String(input.name ?? '').trim();
const email = String(input.email ?? '').trim().toLowerCase();
const company = String(input.company ?? '').trim();
const service = String(input.service ?? '').trim();
const message = String(input.message ?? '').trim();

let employees = input.employees;

if (employees !== undefined && employees !== null && employees !== '') {
  employees = Number(employees);

  if (Number.isNaN(employees)) {
    employees = null;
  }
}

return [
  {
    json: {
      name,
      email,
      company,
      employees,
      service,
      message,

      source: 'website',

      created_at: new Date().toISOString()
    }
  }
];

const data = $json;

const requiredFields = [
  'name',
  'email',
  'company',
  'message'
];

const missingFields = requiredFields.filter((field) => {
  const value = data[field];

  return (
    value === undefined ||
    value === null ||
    String(value).trim() === ''
  );
});

return [
  {
    json: {
      ...data,

      missing_fields: missingFields,

      required_fields_valid: missingFields.length === 0,

      validation_errors: missingFields.map(
        (field) => `${field} is required`
      )
    }
  }
];

const data = $json;

const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

const emailValid = emailRegex.test(data.email);

const validationErrors = [
  ...(data.validation_errors ?? [])
];

if (!emailValid) {
  validationErrors.push('Invalid email format');
}

return [
  {
    json: {
      ...data,

      email_valid: emailValid,

      validation_errors: validationErrors,

      is_valid:
        data.required_fields_valid === true &&
        emailValid === true
    }
  }
];

const now = new Date();

const timestamp =
  now.getFullYear().toString() +
  String(now.getMonth() + 1).padStart(2, '0') +
  String(now.getDate()).padStart(2, '0') +
  '-' +
  String(now.getHours()).padStart(2, '0') +
  String(now.getMinutes()).padStart(2, '0') +
  String(now.getSeconds()).padStart(2, '0');

const random = Math.random()
  .toString(36)
  .substring(2, 7)
  .toUpperCase();

const leadId = `LEAD-${timestamp}-${random}`;

return [
  {
    json: {
      ...$json,

      lead_id: leadId,

      status: 'received',

      duplicate: false
    }
  }
];

const email = String($json.email ?? '')
  .trim()
  .toLowerCase();

const company = String($json.company ?? '')
  .trim()
  .toLowerCase();

const message = String($json.message ?? '')
  .trim()
  .toLowerCase();

const rawKey = `${email}|${company}|${message}`;

// Simple deterministic hash without external modules
let hash = 0;

for (let i = 0; i < rawKey.length; i++) {
  hash = ((hash << 5) - hash) + rawKey.charCodeAt(i);
  hash |= 0;
}

const idempotencyKey = Math.abs(hash).toString(16);

return [
  {
    json: {
      ...$json,
      idempotency_key: idempotencyKey
    }
  }
];

const lead = $('08 - Generate Idempotency Key').first().json;

const lookupResult = $json;

const hasMatch =
  lookupResult &&
  Object.keys(lookupResult).length > 0;

return [
  {
    json: {
      ...lead,
      duplicate: hasMatch,
      duplicate_lead_id: hasMatch
        ? lookupResult.lead_id
        : null
    }
  }
];

return [
  {
    json: {
      timestamp: new Date().toISOString(),

      lead_id: $json.lead_id,

      event: 'lead_saved',

      status: 'success',

      node: '12B - Save Lead',

      message: 'Lead successfully saved to Google Sheets.',

      email: $json.email,

      execution_id: $execution.id,

      metadata: JSON.stringify({
        company: $json.company,
        service: $json.service,
        source: $json.source
      })
    }
  }
];

return [
  {
    json: {
      timestamp: new Date().toISOString(),

      lead_id: $json.lead_id,

      event: 'duplicate_detected',

      status: 'blocked',

      node: '11 - Is Duplicate?',

      message: 'Duplicate lead detected. New row was not created.',

      email: $json.email,

      execution_id: $execution.id,

      metadata: JSON.stringify({
        duplicate_lead_id: $json.duplicate_lead_id,
        company: $json.company,
        service: $json.service
      })
    }
  }
];

const lead = $('12B - Save Lead').first().json;

return [
  {
    json: {
      lead_id: lead.lead_id,
      name: lead.name,
      email: lead.email,
      company: lead.company,
      employees: lead.employees,
      service: lead.service,
      message: lead.message
    }
  }
];

