          },
          "priority": {
            "type": "string",
            "enum": [
              "urgent",
              "high",
              "normal",
              "low"
            ]
          },
          "reason": {
            "type": "string"
          },
          "summary": {
            "type": "string"
          },
          "confidence": {
            "type": "number"
          }
        },
        "required": [
          "lead_score",
          "category",
          "priority",
          "reason",
          "summary",
          "confidence"
        ],
        "additionalProperties": false
      }
    }
  }
}

