const response = $json;

const rawContent = response.choices?.[0]?.message?.content;

if (!rawContent) {
  throw new Error('AI response does not contain message.content');
}

let ai;

try {
  ai = JSON.parse(rawContent);
} catch (error) {
  throw new Error(`AI returned invalid JSON: ${error.message}`);
}

const lead = $('12B - Save Lead').first().json;

if (
  typeof ai.lead_score !== 'number' ||
  ai.lead_score < 0 ||
  ai.lead_score > 100
) {
  throw new Error('Invalid lead_score');
}

const allowedCategories = [
  'high_value',
  'medium_value',
  'low_value'
];

if (!allowedCategories.includes(ai.category)) {
  throw new Error(`Invalid category: ${ai.category}`);
}

const allowedPriorities = [
  'urgent',
  'high',
  'normal',
  'low'
];

if (!allowedPriorities.includes(ai.priority)) {
  throw new Error(`Invalid priority: ${ai.priority}`);
}

if (
  typeof ai.confidence !== 'number' ||
  ai.confidence < 0 ||
  ai.confidence > 1
) {
  throw new Error('Invalid confidence');
}

if (!ai.reason || !ai.summary) {
  throw new Error('AI reason or summary is missing');
}

return [
  {
    json: {
      ...lead,

      lead_score: ai.lead_score,
      category: ai.category,
      priority: ai.priority,
      ai_reason: ai.reason,
      ai_summary: ai.summary,
      ai_confidence: ai.confidence,

      status: 'qualified',

      updated_at: new Date().toISOString()
    }
  }
];

const lead = $('17 - Parse AI Result').first().json;

return [
  {
    json: {
      ...lead,
      route: 'high_value',
      routing_action: 'immediate_sales_notification',
      assigned_to: 'sales',
      status: 'routed'
    }
  }
];

const lead = $('17 - Parse AI Result').first().json;

return [
  {
    json: {
      ...lead,
      route: 'medium_value',
      routing_action: 'sales_notification_and_nurturing',
      assigned_to: 'sales',
      status: 'routed'
    }
  }
];

const lead = $('17 - Parse AI Result').first().json;

return [
  {
    json: {
      ...lead,
      route: 'low_value',
      routing_action: 'nurturing',
      assigned_to: 'nurturing',
      status: 'routed'
    }
  }
];

